"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * LiquidSurface — the bubbly liquid-glass primitive for moneytrees.
 *
 * Wraps any DOM subtree in a glass surface: `backdrop-filter: blur()` via
 * `.mt-liquid-css` plus the bubble radius + shadow tokens from the moneytrees
 * theme. `data-variant` selects the tint (card / nav / modal).
 */
const liquidSurfaceVariants = cva("mt-liquid-css relative", {
  variants: {
    variant: {
      card: "rounded-bubble-md",
      "card-lg": "rounded-bubble-lg",
      pill: "rounded-bubble-pill",
      nav: "rounded-bubble-md",
      modal: "rounded-bubble-lg",
    },
  },
  defaultVariants: { variant: "card" },
});

type LiquidSurfaceProps = Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onAnimationStart" | "onAnimationEnd" | "onDrag" | "onDragStart" | "onDragEnd"
> &
  VariantProps<typeof liquidSurfaceVariants> & {
    /** Apply hover spring (lift on pointer over). Disabled under reduced motion. */
    interactive?: boolean;
    /** Override the data-variant attribute (controls CSS tier tint). */
    surfaceKind?: "card" | "nav" | "modal";
    children?: React.ReactNode;
  };

export const LiquidSurface = React.forwardRef<HTMLDivElement, LiquidSurfaceProps>(
  function LiquidSurface(
    { className, variant, interactive = false, surfaceKind, children, ...rest },
    ref,
  ) {
    const reduced = useReducedMotion();
    const kind = surfaceKind ?? mapVariantToKind(variant);

    if (!interactive || reduced) {
      return (
        <div
          ref={ref}
          data-variant={kind}
          className={cn(liquidSurfaceVariants({ variant }), className)}
          {...rest}
        >
          {children}
        </div>
      );
    }
    return (
      <motion.div
        ref={ref}
        whileHover={{ y: -2 }}
        whileTap={{ scale: 0.985 }}
        transition={{ type: "spring", stiffness: 420, damping: 30 }}
        data-variant={kind}
        className={cn(liquidSurfaceVariants({ variant }), className)}
        {...(rest as React.ComponentProps<typeof motion.div>)}
      >
        {children}
      </motion.div>
    );
  },
);

function mapVariantToKind(
  variant: VariantProps<typeof liquidSurfaceVariants>["variant"],
): "card" | "nav" | "modal" {
  switch (variant) {
    case "nav":
      return "nav";
    case "modal":
      return "modal";
    default:
      return "card";
  }
}
